import pyomo.environ as pyo

DATA = {
    # Foods (rows) and their nutrient content per gram, plus cost per gram.
    # assumption: quantity_units_scale -> x_i = grams of food i, nutrient content per gram
    "foods": ["Chicken", "Tofu", "BrownRice", "Fish", "Lentils",
              "Quinoa", "Eggs", "Beef", "Beans"],
    # data_orientation: rows = foods, columns = nutrients (content[food][nutrient])
    "protein": {
        "Chicken": 7, "Tofu": 12, "BrownRice": 14, "Fish": 9, "Lentils": 11,
        "Quinoa": 10, "Eggs": 10, "Beef": 9, "Beans": 8,
    },
    "carbs": {
        "Chicken": 17, "Tofu": 12, "BrownRice": 27, "Fish": 6, "Lentils": 19,
        "Quinoa": 23, "Eggs": 6, "Beef": 16, "Beans": 25,
    },
    "calories": {
        "Chicken": 95, "Tofu": 233, "BrownRice": 134, "Fish": 109, "Lentils": 202,
        "Quinoa": 148, "Eggs": 184, "Beef": 136, "Beans": 229,
    },
    "cost": {
        "Chicken": 10, "Tofu": 2, "BrownRice": 7, "Fish": 8, "Lentils": 4,
        "Quinoa": 9, "Eggs": 2, "Beef": 9, "Beans": 9,
    },
    # Daily dietary requirements
    "protein_req": 71,
    "carbs_req": 107,
    "calories_req": 1623,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.FOODS = pyo.Set(initialize=d["foods"])

    # assumption: domain_of_food_quantities -> NonNegativeIntegers
    model.x = pyo.Var(model.FOODS, within=pyo.NonNegativeIntegers)

    # "spending as little money as possible" / "minimum cost you need to spend"
    def obj_rule(m):
        return sum(d["cost"][f] * m.x[f] for f in m.FOODS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # "you need at least 71 grams of protein"
    def protein_rule(m):
        return sum(d["protein"][f] * m.x[f] for f in m.FOODS) >= d["protein_req"]

    model.protein_con = pyo.Constraint(rule=protein_rule)

    # "you need at least ... 107 grams of carbohydrates"
    def carbs_rule(m):
        return sum(d["carbs"][f] * m.x[f] for f in m.FOODS) >= d["carbs_req"]

    model.carbs_con = pyo.Constraint(rule=carbs_rule)

    # "you need at least ... 1623 calories" (inclusive)
    def calories_rule(m):
        return sum(d["calories"][f] * m.x[f] for f in m.FOODS) >= d["calories_req"]

    model.calories_con = pyo.Constraint(rule=calories_rule)

    return model


